from pathlib import Path
import base64
import sys

if len(sys.argv) != 2:
    raise SystemExit("Usage: apply_psp_live_flogb_v0_5_7b.py <ppsspp_repo>")

repo = Path(sys.argv[1]).resolve()

def require(rel):
    p = repo / rel
    if not p.exists():
        raise SystemExit(f"Missing expected path: {rel}")
    return p

def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly 1 occurrence, found {count}")
    return text.replace(old, new, 1)

def replace_between(text, start, end, replacement, label):
    a = text.find(start)
    if a < 0:
        raise SystemExit(f"{label}: start marker missing")
    b = text.find(end, a + len(start))
    if b < 0:
        raise SystemExit(f"{label}: end marker missing")
    return text[:a] + replacement + text[b:]

debug = require("UI/DebugOverlay.cpp")
info = require("PSP_LIVE_FLOGB_BUILD_INFO.txt")
s = debug.read_text(encoding="utf-8")

for marker in ("WINNER VISUAL V2 LAB", "DrawSCBDWinnerPortraitGrid", "DrawSCBDWinnerCountdown", "P%d VICTORY", "TOP 1 WINNER", "LOCKED IN", "GAME RANDOM", "DrawSCBDMatchTop5HUD", "SCBD_LEGACY_MEMORY_INSPECTOR_VISIBLE = false"):
    if marker not in s:
        raise SystemExit(f"V0.5.7B prerequisite missing: {marker}")

asset_dir = repo / "assets/scbd/winner_royal"
asset_dir.mkdir(parents=True, exist_ok=True)
ASSETS = {
    'winner_locked.png': '',
    'winner_pick.png': '',
    'winner_timeout.png': '',
    'winner_victory.png': '',
}
for name, payload in ASSETS.items():
    data = base64.b64decode(payload)
    (asset_dir / name).write_bytes(data)
    if len(data) < 1024:
        raise SystemExit(f"V0.5.7B asset too small: {name}")

ROYAL_RENDERER_B64 = ''
royal_renderer = base64.b64decode(ROYAL_RENDERER_B64).decode("utf-8")
s = replace_between(s, "static void DrawSCBDWinnerPortraitGrid(", "static void DrawSCBDBoneMapper(", royal_renderer, "replace Winner V2 renderer with Royal Gold Ceremony")

diag_old = """    ctx->Draw()->SetFontScale(0.38f, 0.38f);
    ctx->Draw()->DrawTextRect(
        ubuntu24,
        summary,
        bounds.x + 12.0f,
        bounds.y + bounds.h - 34.0f,
        bounds.w - 24.0f,
        28.0f,
        0xFFFFFFFF,
        FLAG_DYNAMIC_ASCII
    );
"""
diag_new = """    // V0.5.7B: tracking stays live, diagnostic text is hidden in normal gameplay.
    static constexpr bool SCBD_RUNTIME_DIAGNOSTIC_VISIBLE = false;
    if (SCBD_RUNTIME_DIAGNOSTIC_VISIBLE) {
        ctx->Draw()->SetFontScale(0.38f, 0.38f);
        ctx->Draw()->DrawTextRect(
            ubuntu24,
            summary,
            bounds.x + 12.0f,
            bounds.y + bounds.h - 34.0f,
            bounds.w - 24.0f,
            28.0f,
            0xFFFFFFFF,
            FLAG_DYNAMIC_ASCII
        );
    }
"""
s = replace_once(s, diag_old, diag_new, "hide runtime diagnostic line")
s = replace_once(s, "WINNER VISUAL V2 LAB | Web Winner V5 van la fallback LIVE", "WINNER ROYAL V0.5.7B | Web Winner V5 van la fallback LIVE", "rename Winner Royal lab")
debug.write_text(s, encoding="utf-8")

final = debug.read_text(encoding="utf-8")
for marker in ("GetSCBDWinnerRoyalTexture", "winner_victory.png", "winner_pick.png", "winner_locked.png", "winner_timeout.png", "P%d VICTORY", "TOP 1 WINNER", "LOCKED IN", "GAME RANDOM", "SCBD_RUNTIME_DIAGNOSTIC_VISIBLE = false", "WINNER ROYAL V0.5.7B", "DrawSCBDMatchTop5HUD", "SCBDVirtualInput::Process();"):
    if marker not in final:
        raise SystemExit(f"V0.5.7B generated source missing: {marker}")
for name in ASSETS:
    p = asset_dir / name
    if not p.exists() or p.stat().st_size < 1024:
        raise SystemExit(f"V0.5.7B generated asset invalid: {name}")
with info.open("a", encoding="utf-8") as f:
    f.write("\nPSP Live FloGB V0.5.7B Winner Visual Polish Pass 1\nArt direction: approved Style A - Royal Gold Ceremony\nWinner Intro: gold crown/laurel/emerald ribbon overlay + cinematic P1/P2 VICTORY\nPick Phase: royal winner card, Top1 identity, score, /pick 1-28, countdown, 28 portraits\nLocked In: royal portrait presentation + selected slot highlight\nTimeout: TIME OUT -> GAME RANDOM only; Soulcalibur still owns random selection\nRuntime debug line hidden in normal mode; tracking backend remains active\nInput Core V1 and ranking/HUD behavior preserved\n")
print("PSP Live FloGB V0.5.7B Winner Visual Polish Pass 1 patch applied successfully.")
